                [
                    'title' => $event['title'],
                    'slug' => $slug,
                    'date' => $event['date'],
                    'venue' => $event['venue'],
                    'description' => $event['description'],
                    'status' => $event['status'],
                    'is_major' => $event['is_major'] ?? false,
                ]
            );
        }

        // Mark the 3 most recent events as major
